?><!doctype html><html lang="zh-CN" data-withu-theme="<?php echo e($themeConfig['preset']); ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>地图与足迹 - withU</title><link rel="stylesheet" href="/assets/css/style.css?v=withu-logo-20260718"><link rel="stylesheet" href="/assets/css/theme.css?v=withu-theme-20260719-3"><link rel="stylesheet" href="/assets/css/withu-sakura.css?v=withu-map-1"><link rel="stylesheet" href="/assets/css/travel-map.css?v=withu-travel-1"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" crossorigin=""><link rel="stylesheet" href="https://unpkg.com/leaflet-fullscreen@1.0.2/dist/leaflet.fullscreen.css"><link rel="stylesheet" href="/admin-assets/vendor/fontawesome/css/all.min.css"></head><body class="withu-front-modern withu-travel-page"><main class="travel-map-shell"><header class="travel-map-head"><div><span class="travel-kicker"><i class="fas fa-location-dot"></i> OUR SHARED JOURNEY</span><h1>地图与足迹</h1><p>把走过的路、去过的地方和此刻的位置，放进我们的共同地图。</p></div><div class="travel-head-actions"><a class="travel-pill" href="/">返回首页</a><?php if($user): ?><a class="travel-pill" href="/admin/map.php">管理</a><?php endif; ?></div></header>
<section id="map" class="travel-map-card"><div class="travel-map-toolbar"><div class="travel-map-status"><i class="fas fa-map"></i><span id="mapStatus">正在加载地图数据…</span></div><div class="travel-map-tools"><button type="button" class="travel-tool" id="locateMe"><i class="fas fa-crosshairs"></i> 定位我</button><button type="button" class="travel-tool" id="drawRoute"><i class="fas fa-route"></i> 添加路线点</button><button type="button" class="travel-tool" id="clearRoute"><i class="fas fa-eraser"></i> 清除</button></div></div><div id="coupleMap" class="couple-map" aria-label="情侣地图"></div><div class="travel-map-legend"><span><i class="map-dot map-dot-me"></i>情侣位置</span><span><i class="map-dot map-dot-memory"></i>共同足迹</span><span><i class="map-line"></i>路线</span></div></section>
<section class="travel-map-grid"><div class="travel-card"><div class="travel-card-title"><i class="fas fa-location-crosshairs"></i><div><h2>保存情侣位置</h2><p>可以使用浏览器定位，也可以手动填写坐标。</p></div></div><div class="travel-form-grid"><label>地点名称<input id="positionName" placeholder="例如：家 / 公司"></label><label>可见范围<select id="positionVisibility"><option value="couple">仅情侣</option><option value="public">公开</option><option value="private">仅自己</option></select></label><label>纬度<input id="positionLat" type="number" step="any" placeholder="39.9042"></label><label>经度<input id="positionLng" type="number" step="any" placeholder="116.4074"></label></div><button class="travel-primary" id="savePosition"><i class="fas fa-heart"></i> 保存我的位置</button></div><div class="travel-card"><div class="travel-card-title"><i class="fas fa-bookmark"></i><div><h2>记录一个足迹</h2><p>搜索或填写我们去过的地点。</p></div></div><div class="travel-form-grid"><label>地点标题<input id="locationTitle" placeholder="例如：第一次看海"></label><label>地点名称<input id="locationName" placeholder="例如：厦门环岛路"></label><label>纬度<input id="locationLat" type="number" step="any" placeholder="24.48"></label><label>经度<input id="locationLng" type="number" step="any" placeholder="118.09"></label><label>访问日期<input id="visitDate" type="date"></label><label>描述<input id="locationDesc" placeholder="写一句我们的回忆"></label></div><label class="travel-check"><input id="locationFavorite" type="checkbox"> 标记为最喜欢的地方</label><button class="travel-primary" id="saveLocation"><i class="fas fa-plus"></i> 保存足迹</button></div></section>
<section class="travel-card travel-route-card"><div class="travel-card-title"><i class="fas fa-route"></i><div><h2>保存路线</h2><p>点击“添加路线点”，再在地图上依次点击起点和终点（可添加多个点）。</p></div></div><div class="travel-form-grid"><label>路线名称<input id="routeTitle" placeholder="例如：周末海边路线"></label><label>起点名称<input id="routeStart" placeholder="起点"></label><label>终点名称<input id="routeEnd" placeholder="终点"></label><label>路线距离（公里）<input id="routeDistance" type="number" step="any" placeholder="自动或手动填写"></label></div><button class="travel-primary" id="saveRoute"><i class="fas fa-save"></i> 保存当前路线</button><span id="routeHint" class="travel-inline-hint">尚未绘制路线</span></section>
<section class="travel-map-grid travel-lower-grid"><div class="travel-card"><div class="travel-card-title"><i class="fas fa-clock-rotate-left"></i><div><h2>我们的足迹</h2><p>按时间记录共同去过的地方。</p></div></div><div id="locationTimeline" class="location-timeline"><div class="travel-empty">正在加载…</div></div></div><div class="travel-card"><div class="travel-card-title"><i class="fas fa-cloud-sun"></i><div><h2>天气与旅行规划</h2><p>保留 WithU 原有天气和 AI 规划能力。</p></div></div><div class="travel-form-grid"><label>纬度<input id="lat" type="number" step="any" placeholder="纬度"></label><label>经度<input id="lng" type="number" step="any" placeholder="经度"></label><label>目的地<input id="destination" placeholder="目的地"></label><label>开始日期<input id="start" type="date"></label><label>结束日期<input id="end" type="date"></label><label>需求<input id="prompt" placeholder="两天、轻松、适合拍照"></label></div><div class="travel-actions"><button class="travel-primary" id="weather">查询天气</button><button class="travel-secondary" id="plan">生成计划</button></div><pre id="weatherOut"></pre><pre id="planOut"></pre></div></section></main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" crossorigin=""></script><script src="https://unpkg.com/leaflet-fullscreen@1.0.2/dist/Leaflet.fullscreen.min.js"></script><script>
(function(){'use strict';var csrf=<?php echo json_encode($csrf); ?>,map=L.map('coupleMap',{zoomControl:true,fullscreenControl:true}).setView([35.86,104.19],4),markers=[],routePoints=[],routeLine=null,drawing=false;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);function el(id){return document.getElementById(id)}function val(id){return el(id).value.trim()}function msg(t){el('mapStatus').textContent=t}function post(action,data){data=data||{};data._token=csrf;return fetch('/api/travel_map.php?action='+action,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(data)}).then(function(r){return r.json()})}function icon(cls){return L.divIcon({className:'withu-map-marker '+cls,html:'<i class="fas fa-heart"></i>',iconSize:[34,34],iconAnchor:[17,17]})}function clearMarkers(){markers.forEach(function(m){map.removeLayer(m)});markers=[]}function addMarker(item,kind){var lat=Number(item.latitude),lng=Number(item.longitude);if(!isFinite(lat)||!isFinite(lng))return;var m=L.marker([lat,lng],{icon:icon(kind==='memory'?'is-memory':'is-position')}).addTo(map);var title=item.title||item.location_name||item.nickname||'情侣位置';var date=item.visit_date||item.updated_at||'';m.bindPopup('<strong>'+escapeHtml(title)+'</strong><br><span>'+escapeHtml(item.location_name||'')+'</span><br><small>'+escapeHtml(date)+'</small>');markers.push(m)}function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}function render(data){clearMarkers();var all=[];(data.positions||[]).forEach(function(p){addMarker(p,'position');all.push([Number(p.latitude),Number(p.longitude)])});(data.locations||[]).forEach(function(p){addMarker(p,'memory');all.push([Number(p.latitude),Number(p.longitude)])});(data.routes||[]).forEach(function(r){var pts=(r.points||[]).map(function(p){return[Number(p.lat),Number(p.lng)]});if(pts.length>1)L.polyline(pts,{color:'#ec4899',weight:4,opacity:.75}).addTo(map)});var bounds=all.filter(function(p){return isFinite(p[0])&&isFinite(p[1])});if(bounds.length)map.fitBounds(bounds,{padding:[35,35],maxZoom:13});var list=el('locationTimeline');if(!(data.locations||[]).length)list.innerHTML='<div class="travel-empty">还没有足迹，保存第一个共同地点吧。</div>';else list.innerHTML=data.locations.map(function(p){return '<article class="location-item"><span class="location-item-dot"></span><div><strong>'+escapeHtml(p.title)+'</strong><p>'+escapeHtml(p.location_name||'')+' · '+escapeHtml(p.visit_date||'未填写日期')+'</p><small>'+escapeHtml(p.description||'')+'</small></div><button type="button" data-delete-location="'+p.id+'" aria-label="删除"><i class="fas fa-trash"></i></button></article>'}).join('');list.querySelectorAll('[data-delete-location]').forEach(function(b){b.onclick=function(){if(confirm('删除这个足迹？'))post('delete_location',{id:b.dataset.deleteLocation}).then(function(r){if(r.success)render(r)})}})}function load(){fetch('/api/travel_map.php?action=snapshot').then(function(r){return r.json()}).then(function(r){if(r.success){render(r);msg('地图数据已同步 · '+((r.locations||[]).length)+' 个足迹')}else msg(r.message||'地图加载失败')}).catch(function(){msg('地图服务暂时不可用')})}map.on('click',function(e){if(drawing){routePoints.push({lat:e.latlng.lat,lng:e.latlng.lng});if(routeLine)map.removeLayer(routeLine);routeLine=L.polyline(routePoints.map(function(p){return[p.lat,p.lng]}),{color:'#ec4899',weight:4,dashArray:'8 8'}).addTo(map);el('routeHint').textContent='已添加 '+routePoints.length+' 个路线点'}});el('drawRoute').onclick=function(){drawing=true;routePoints=[];if(routeLine)map.removeLayer(routeLine);el('routeHint').textContent='请在地图上点击路线点，完成后点击保存'};el('clearRoute').onclick=function(){drawing=false;routePoints=[];if(routeLine)map.removeLayer(routeLine);routeLine=null;el('routeHint').textContent='尚未绘制路线'};el('locateMe').onclick=function(){if(!navigator.geolocation)return alert('浏览器不支持定位');navigator.geolocation.getCurrentPosition(function(p){var lat=p.coords.latitude,lng=p.coords.longitude;map.setView([lat,lng],14);el('positionLat').value=lat.toFixed(7);el('positionLng').value=lng.toFixed(7)},function(){alert('定位失败，请检查浏览器权限')},{enableHighAccuracy:true,timeout:10000})};el('savePosition').onclick=function(){post('save_position',{location_name:val('positionName'),visibility:val('positionVisibility'),latitude:val('positionLat'),longitude:val('positionLng')}).then(function(r){if(!r.success)return alert(r.message);render(r);msg(r.message)})};el('saveLocation').onclick=function(){post('save_location',{title:val('locationTitle'),location_name:val('locationName'),description:val('locationDesc'),latitude:val('locationLat'),longitude:val('locationLng'),visit_date:val('visitDate'),is_favorite:el('locationFavorite').checked?1:0}).then(function(r){if(!r.success)return alert(r.message);render(r);msg(r.message)})};el('saveRoute').onclick=function(){post('save_route',{title:val('routeTitle'),start_name:val('routeStart'),end_name:val('routeEnd'),distance_km:val('routeDistance'),points:routePoints}).then(function(r){if(!r.success)return alert(r.message);render(r);el('clearRoute').click();msg(r.message)})};el('weather').onclick=function(){fetch('/api/travel.php?action=weather&lat='+encodeURIComponent(val('lat'))+'&lng='+encodeURIComponent(val('lng'))).then(function(r){return r.json()}).then(function(r){el('weatherOut').textContent=r.success?JSON.stringify(r.data,null,2):r.message})};el('plan').onclick=function(){postPlan()};function postPlan(){var d={destination:val('destination'),start_date:val('start'),end_date:val('end'),prompt:val('prompt'),_token:csrf};fetch('/api/travel.php?action=plan',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(d)}).then(function(r){return r.json()}).then(function(r){el('planOut').textContent=r.success?JSON.stringify(r.plan,null,2):r.message})}load();window.setTimeout(function(){map.invalidateSize()},400)})();
</script></body></html>
